window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[341]={"id":"341","numero":341,"titre":"Hémorragie méningée non traumatique","objectifs":[{"id":"341-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hémorragie méningée dite sous-arachnoïdienne, spontanée et traumatique","contenu":"<div class=\"notion-course\"><p>L'<span>hémorragie méningée</span> — ou hémorragie <span>sous-arachnoïdienne</span> (HSA) — se définit par la présence de <span>sang</span> dans les <span>espaces sous-arachnoïdiens</span>.</p>\n      <p>Les <span>espaces sous-arachnoïdiens</span> (ESA) sont limités par la <span><span class=\"nc-blue_bg\">pie-mère</span></span><span class=\"nc-blue_bg\"> sur le versant cérébral (interne)</span> et par l'<span><span class=\"nc-blue_bg\">arachnoïde</span></span><span class=\"nc-blue_bg\"> sur le versant externe</span>. Ils entourent le cerveau, contiennent le <span><span class=\"nc-pink_bg\">LCS</span></span> ainsi que des artères et des veines de gros calibre, et sont de plus grande taille à la base du crâne où ils forment les <span><span class=\"nc-purple_bg\">citernes de la base</span></span>.</p>\n      <p><strong>Distinction sémantique essentielle</strong> — deux causes à séparer :</p>\n      <ul>\n        <li><strong>HSA spontanée :</strong> <span>urgence vitale</span>, secondaire à une <span>rupture d'anévrisme artériel intra-crânien</span> jusqu'à preuve du contraire.</li>\n        <li>HSA traumatique : prise en charge selon la gravité du traumatisme et les lésions associées. Elle peut nécessiter des soins urgents, même si elle ne relève pas habituellement de l’exclusion d’un anévrisme.</li>\n      </ul>\n      <table>\n        <thead><tr><th><span>Épidémiologie</span> (HSA non traumatique)</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td><span>Incidence</span></td><td><span>10 cas / 100 000 habitants</span> (×2 au Japon et en Finlande)</td></tr>\n          <tr><td>Âge</td><td>Touche des <span class=\"nc-pink_bg\">sujets jeunes sans ATCD</span> ; âge médian <span><span class=\"nc-pink nc-bold\">55 ans</span></span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance <span class=\"nc-pink nc-bold\">féminine</span> — <span>1,6 F / 1 H</span></td></tr>\n          <tr><td><span>Mortalité</span></td><td><span>40-50 %</span> globale, dont <span>10-20 %</span> de décès en pré-hospitalier</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li></ul><p></p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/subarachnoid-space","label":"Radiopaedia : Subarachnoid space"}]},{"id":"341-2","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d’hémorragies méningées et les facteurs favorisants","contenu":"<div class=\"notion-course\"><p>Trois grands cadres étiologiques se répartissent la quasi-totalité des HSA non traumatiques :</p>\n      <table>\n        <thead><tr><th>Fréquence</th><th>Catégorie</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span>85 %</span></td><td><span>Rupture d'anévrisme artériel</span></td><td>Communicante antérieure <span>40 %</span>, <span class=\"nc-pink_bg\">carotide interne</span> <span>30 %</span>, <span class=\"nc-pink_bg\">cérébrale moyenne</span> <span>20 %</span>, <span class=\"nc-pink_bg\">système vertébro-basilaire</span> <span>10 %</span></td></tr>\n          <tr><td><span>10 %</span></td><td><span>HSA non anévrismale péri-mésencéphalique</span></td><td><strong>Diagnostic d'exclusion</strong> ; saignement peu abondant de la citerne interpédonculaire ; <span>physiopathologie</span> méconnue ; <span><span class=\"nc-green nc-bold\">bon pronostic</span></span>, récidive exceptionnelle</td></tr>\n          <tr><td><span>5 %</span></td><td>Causes rares</td><td>Tumeurs ; lésions inflammatoires des artères (<span>Behçet</span>, angéite primaire, <span>Wegener</span>, anévrisme mycotique) ; <span>MAV</span>, <span>fistule</span> durale, cavernome ; <span>dissection artérielle</span> ; <span>angiopathie amyloïde</span> (HSA corticales) ; coagulopathies ; toxiques</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Anévrisme artériel intra-crânien</strong> — formation et <span>rupture</span> :</p>\n      <table>\n        <thead><tr><th>Concept</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Définition</td><td><span class=\"nc-yellow_bg\">Perte de parallélisme de la paroi artérielle</span> par déhiscence de la <span><span class=\"nc-pink nc-bold\">limitante élastique interne</span></span> → <span class=\"nc-blue_bg\">dilatation sacciforme</span> (rarement fusiforme), <span>diamètre</span> <span><span class=\"nc-pink nc-bold\">&lt; 10 mm</span></span> dans <span>90 %</span> des cas</td></tr>\n          <tr><td>Localisations</td><td><span class=\"nc-yellow_bg\">Bifurcations</span> <span class=\"nc-yellow_bg\">artérielles</span> des grosses artères à destinée cérébrale, situées sur le <span>polygone de Willis</span> (dans les <span class=\"nc-purple_bg\">citernes de la base</span>)</td></tr>\n          <tr><td>FR de formation</td><td><span><span class=\"nc-orange_bg\">HTA</span></span> ; <span><span class=\"nc-orange_bg\">tabac</span></span>, <span class=\"nc-orange_bg\">alcool</span> ; <span class=\"nc-blue_bg\">facteurs hémodynamiques</span> (turbulence rhéologique aux <span class=\"nc-yellow_bg\">bifurcations</span>)</td></tr>\n          <tr><td><span>Physiopathologie</span></td><td>Paroi anévrismale plus fragile qu'une artère saine → fissuration possible, puis <span>rupture</span></td></tr>\n          <tr><td>FR de <span>rupture</span></td><td>Le risque dépend de la taille, de la localisation, de la morphologie, d’une croissance et du terrain. Un petit anévrisme peut rompre ; aucun seuil de taille ne rend le risque nul.</td></tr>\n          <tr><td>Complications du saignement</td><td><span class=\"nc-orange_bg\">Hématome intra-parenchymateux</span> (anévrisme enchâssé) ; <span class=\"nc-orange_bg\">hémorragie intra-ventriculaire</span> (<span>rupture</span> près des ventricules) ; exceptionnellement <span class=\"nc-orange_bg\">hématome sous-dural aigu</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Facteurs de risque</span> d'HSA</strong> :</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td>Modifiables</td><td>\n            <ul>\n              <li><span><span class=\"nc-orange_bg\">Tabagisme</span></span> — FR le plus péjoratif</li>\n              <li><span>HTA</span></li>\n              <li><span class=\"nc-orange_bg\">Intoxication alcoolique chronique</span></li>\n            </ul>\n          </td></tr>\n          <tr><td>Non modifiables</td><td>\n            <ul>\n              <li><span class=\"nc-pink_bg\">Sexe féminin</span> (sex-ratio <span>1,6 F / 1 H</span>)</li>\n              <li><span>ATCD familiaux d'HSA anévrismale</span> — risque majoré si <span>≥ 2 membres</span> du 1ᵉʳ degré</li>\n              <li><span class=\"nc-orange_bg\">ATCD personnels d'anévrisme intra-crânien</span></li>\n              <li>Coarctation de l'aorte</li>\n              <li>Affections héréditaires du tissu conjonctif : <span><span class=\"nc-red_bg\">polykystose rénale</span></span> (en 1ᵉʳ lieu), <span class=\"nc-red_bg\">NF1</span>, <span class=\"nc-red_bg\">Marfan</span>, Ehlers-Danlos</li>\n            </ul>\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 266 — <span class=\"nc-red_bg\">Polykystose rénale</span> · 152 — Endocardite infectieuse</em></p><p>Une HSA de convexité doit également faire rechercher une vasoconstriction cérébrale réversible, une TVC ou une angiopathie amyloïde selon l’âge et le contexte. Ne pas qualifier une HSA de « bénigne » avant le bilan étiologique.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li></ul><p></p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/circle-of-willis","label":"Radiopaedia : Circle of willis"},{"href":"https://radiopaedia.org/articles/saccular-cerebral-aneurysm","label":"Radiopaedia : Saccular cerebral aneurysm"}]},{"id":"341-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les présentations cliniques et le diagnostic d’hémorragie méningée","contenu":"<div class=\"notion-course\"><div class=\"callout\"><p>Une céphalée atteignant son maximum en moins d’une minute définit le coup de tonnerre : rechercher une HSA en urgence. Un syndrome méningé, une perte de connaissance ou une paralysie du III peuvent aussi alerter. L’absence de raideur, de déficit ou de céphalée typique n’exclut pas l’HSA.</p></div>\n      <p>Le tableau typique associe une <strong><span>céphalée</span> brutale</strong> et un <strong><span>syndrome méningé</span></strong>, sans <span>fièvre</span>.</p>\n      <table>\n        <thead><tr><th>Composante</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span>Céphalée</span> (quasi-constante)</td><td><strong>Caractères :</strong> précoce, récente, <span class=\"nc-red nc-bold\">inhabituelle</span>, mal soulagée par les <span>antalgiques</span> habituels<br><strong>Topographie :</strong> en <span><span class=\"nc-blue_bg nc-bold\">casque</span></span> ou diffuse<br><strong>Facteurs aggravants :</strong> <span class=\"nc-red nc-bold\">mouvements de la tête</span> ; <span class=\"nc-red nc-bold\">examen physique</span> ; <span><span class=\"nc-red nc-bold\">photophobie</span></span> ; <span><span class=\"nc-red nc-bold\">phonophobie</span></span></td></tr>\n          <tr><td><span>Vomissements</span></td><td><strong>Caractères :</strong> en jet (ou simples <span>nausées</span>), inconstants, généralement précoces<br><strong>Favorisés par :</strong> les changements de position<br><strong>Particularité :</strong> peuvent soulager la <span>céphalée</span></td></tr>\n          <tr><td>Raideur méningée</td><td><strong>Attitude :</strong> en <span>« <span class=\"nc-blue_bg nc-bold\">chien de fusil</span> »</span> (décubitus latéral, tête en hyperextension, membres semi-fléchis)<br><strong>Nuque :</strong> résistance invincible et douloureuse à la flexion ; rotation conservée mais augmente la <span>céphalée</span><br><strong>Kernig :</strong> cuisses fléchies sur le bassin jambes étendues → la douleur force la flexion des jambes<br><strong>Brudzinski :</strong> flexion passive de la nuque → flexion des 2 membres inférieurs</td></tr>\n          <tr><td>Autres signes</td><td><strong>Signes associés :</strong> <span class=\"nc-blue_bg\">raie méningitique de Trousseau</span> ; <span class=\"nc-blue_bg\">hyperesthésie cutanée diffuse</span> ; <span><span class=\"nc-blue_bg\">ROT vifs</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Tableaux atypiques</strong> à connaître :</p>\n      <ul>\n        <li><span>Céphalée</span> modérée mais <strong>toujours brutale</strong>, parfois plus postérieure (occipitale ou rachidienne)</li>\n        <li><span>Céphalée</span> plus progressive dans les HSA de faible abondance ; céphalée parfois isolée</li>\n        <li><span><span class=\"nc-brown_bg\">Perte de connaissance initiale</span></span><span class=\"nc-brown_bg\"> avec récupération rapide</span></li>\n        <li><span><span class=\"nc-brown_bg\">Syndrome confusionnel aigu</span></span>, <span><span class=\"nc-brown_bg\">crise d'épilepsie généralisée</span></span>, voire <span><span class=\"nc-brown_bg\">état de mal</span></span></li>\n        <li><span>Coma d'emblée</span> (<span><span class=\"nc-red_bg\">HTIC</span></span><span class=\"nc-red_bg\"> aiguë</span> ou <span class=\"nc-red_bg\">hydrocéphalie aiguë</span>)</li>\n        <li>Forme grave avec coma ou arrêt cardiorespiratoire ; rechercher l’origine neurologique après stabilisation selon contexte.</li>\n      </ul>\n      <p><strong>Signes associés évocateurs</strong> :</p>\n      <table>\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span>Syndrome de Terson</span> (<span>20 %</span>)</td><td><strong>Mécanisme :</strong> hémorragies intra-oculaires uni- ou bilatérales (intra-vitréennes ou rétiniennes)<br><strong>Clinique :</strong> <span><span class=\"nc-blue_bg\">myodésopsies</span></span>, <span>baisse de l'acuité visuelle</span><br><strong>Diagnostic :</strong> <span>fond d'œil</span> — hémorragies sous-hyaloïdiennes proches de la papille</td></tr>\n          <tr><td>Diplopie</td><td><strong>Mécanisme :</strong> atteinte du <span>III</span> par compression d'un anévrisme volumineux de la portion supraclinoïdienne de la <span class=\"nc-pink_bg\">carotide interne</span> (naissance de la communicante postérieure)<br><strong>Signes :</strong> <span>mydriase aréactive</span>, ptosis, <span>strabisme divergent</span></td></tr>\n          <tr><td>Déficit neurologique</td><td><strong>Rare en initial :</strong> signe une <span>hémorragie cérébro-méningée</span> (HSA + <span class=\"nc-orange_bg\">hématome intra-parenchymateux</span>) ou un <span><span class=\"nc-red_bg\">vasospasme</span></span> (après J4)</td></tr>\n          <tr><td>Signes végétatifs (<span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">24 h</span></span>)</td><td><strong>Cardiaques :</strong> brady- ou <span>tachycardie</span>, modifications <span>ECG</span> mimant un <span>IDM</span>, troubles du rythme<br><strong>Hémodynamiques :</strong> <span>choc</span> avec <span><span class=\"nc-orange_bg\">OAP</span></span> (orage catécholaminergique → <span><span class=\"nc-orange_bg\">tako-tsubo</span></span>), instabilité tensionnelle<br><strong>Général :</strong> <span><span class=\"nc-blue_bg\">hyperthermie</span></span><span class=\"nc-blue_bg\"> retardée</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span>Céphalée</span> · 105 — <span class=\"nc-orange_bg\">Epilepsie</span> · 343 — Etat confusionnel - trouble de conscience · 91 — Déficit neuro récent</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li></ul><p></p></details>","frequence":2},{"id":"341-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","contenu":"<div class=\"notion-course\"><h4>Céphalée brutale : confirmer ou poursuivre les investigations</h4><ol><li>Évaluer et stabiliser les fonctions vitales ; TDM cérébrale sans injection en urgence. La sensibilité dépend notamment du délai, de la qualité technique et de la lecture.</li><li>HSA visible : avis spécialisé immédiat et exploration vasculaire, habituellement angio-TDM, pour rechercher la cause et les complications.</li><li>TDM négative mais suspicion persistante : réévaluer délai, qualité et probabilité clinique avec l’équipe ; ne pas conclure automatiquement à une céphalée bénigne.</li><li>PL si indiquée et sans contre-indication ; pour la recherche de <span class=\"nc-pink nc-bold\">bilirubine</span>/xanthochromie, attendre au moins 12 h après le début selon NICE. Cela n’autorise pas à différer l’imagerie ni la surveillance.</li><li>PL impossible, résultats équivoques ou présentation tardive : investigations spécialisées, pouvant inclure IRM et imagerie vasculaire. Aucune sensibilité de 100 % ne doit être promise.</li></ol><div class=\"callout\"><p>La PL est évitée en cas de menace d’engagement, d’effet de masse ou d’hydrocéphalie obstructive ; contrôler également hémostase, traitements anticoagulants et stabilité clinique. Une TDM normale ne garantit pas à elle seule la sécurité de la PL.</p></div><p>Les protocoles modernes peuvent dispenser de PL après une TDM très précoce de qualité dans des conditions précises. Cette décision est spécialisée : ne pas appliquer une règle horaire isolée.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li><li><a href=\"https://www.nice.org.uk/guidance/ng228/chapter/Recommendations\" target=\"_blank\" rel=\"noopener noreferrer\">NICE NG228 · Diagnostic et prise en charge de l’HSA</a></li></ul><p></p></details>","frequence":0},{"id":"341-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","contenu":"<div class=\"notion-course\"><p>Le <span>TDM cérébral sans injection</span> est l'examen pivot du <span>diagnostic positif</span> d'HSA, à réaliser en <span>urgence</span>.</p>\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Signe direct</td><td><span><span class=\"nc-yellow_bg\">Hyperdensité</span> <span class=\"nc-yellow_bg\">spontanée</span></span><span class=\"nc-yellow_bg\"> des </span><span><span class=\"nc-yellow_bg\">espaces sous-arachnoïdiens</span></span></td></tr>\n          <tr><td>Localisations typiques</td><td><span><span class=\"nc-purple_bg\">Citernes de la base</span></span> ; <span>vallée sylvienne</span> (scissure latérale) ; <span>scissure interhémisphérique</span> (longitudinale) ; <span><span class=\"nc-purple_bg\">sillons corticaux</span></span></td></tr>\n          <tr><td>Sensibilité</td><td>Meilleure dans les premières heures ; diminue avec le temps et dépend de la qualité du scanner, du volume de sang et de la lecture.</td></tr>\n          <tr><td>Faux négatif</td><td>Si la suspicion persiste, compléter selon délai et protocole spécialisé ; une TDM négative n’arrête pas automatiquement le bilan.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Orientations étiologiques au <span>TDM</span></strong> :</p>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Calcifications de la paroi anévrismale</span></span> (rare) = visualisation directe d'un anévrisme</li>\n        <li><span><span class=\"nc-red nc-bold\">HSA corticale</span></span> = doit faire suspecter une étiologie non anévrismale → <span>angiopathie amyloïde</span> (++), <span><span class=\"nc-red nc-bold\">MAV</span></span>, <span>thrombose veineuse cérébrale</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Rechercher dès le <span>TDM</span> initial les complications visibles : <span><span class=\"nc-orange_bg\">hématome intra-parenchymateux</span> associé</span>, <span><span class=\"nc-orange_bg\">hémorragie intra-ventriculaire</span></span>, <span><span class=\"nc-red_bg\">hydrocéphalie aiguë</span></span> (<span>dilatation ventriculaire</span>).\n      </div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li><li><a href=\"https://www.nice.org.uk/guidance/ng228/chapter/Recommendations\" target=\"_blank\" rel=\"noopener noreferrer\">NICE NG228 · Diagnostic et prise en charge de l’HSA</a></li></ul><p></p></details>","frequence":0},{"id":"341-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","contenu":"<div class=\"notion-course\"><h4>Interpréter le LCS avec le délai et le laboratoire</h4><table><thead><tr><th>Donnée</th><th>Interprétation</th></tr></thead><tbody><tr><td>Hématies</td><td>Peuvent traduire HSA ou ponction traumatique ; leur présence ne tranche pas seule.</td></tr><tr><td>Xanthochromie / <span class=\"nc-pink nc-bold\">bilirubine</span></td><td>Recherche dans le surnageant, préférentiellement selon méthode spectrophotométrique validée ; délai d’au moins 12 h pour cette stratégie.</td></tr><tr><td>Évolution entre tubes</td><td>Une diminution des hématies suggère une ponction traumatique, sans exclure à elle seule une HSA.</td></tr><tr><td>Pression, protéines, cellules</td><td>Données complémentaires non spécifiques ; la pression d’ouverture n’est pas obligatoirement élevée.</td></tr><tr><td>Résultat négatif ou équivoque</td><td>Tenir compte du délai, de la qualité du prélèvement, de l’analyse et de la probabilité clinique ; contrôle spécialisé si discordance.</td></tr></tbody></table><div class=\"callout\"><p>Ni la coagulation du prélèvement ni son éclaircissement entre les tubes ne suffisent à éliminer l’HSA. Éviter les assertions « xanthochromie dans 100 % des cas » ou « PL normale toujours éliminatoire ». Le rendement diminue dans les présentations tardives.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li><li><a href=\"https://www.nice.org.uk/guidance/ng228/chapter/Recommendations\" target=\"_blank\" rel=\"noopener noreferrer\">NICE NG228 · Diagnostic et prise en charge de l’HSA</a></li></ul><p></p></details>","frequence":0},{"id":"341-7","rang":"A","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","contenu":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-yellow_bg\">hyperdensité</span> <span class=\"nc-yellow_bg\">spontanée</span></span><span class=\"nc-yellow_bg\"> des espaces sous-arachnoïdiens</span> est le signe pivot du diagnostic <span>TDM</span>. Voici un exemple typique sur coupe axiale non injectée :</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/341/tdm-hsa-ventriculaire.png\" alt=\"TDM cérébrale axiale non injectée : hémorragie sous-arachnoïdienne avec extension intra-ventriculaire droite\">\n        <figcaption>Hémorragie sous-arachnoïdienne avec extension <span>intra-ventriculaire droite</span> (hyperdensité spontanée comblant les sillons et le ventricule latéral droit).</figcaption>\n      </figure>\n      <p><strong>Sémiologie à reconnaître :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-yellow_bg\">Hyperdensité</span> spontanée</span> des <span class=\"nc-purple_bg\">citernes de la base</span> (citerne interpédonculaire, citerne pré-pontique, citernes ambiantes)</li>\n        <li><span>Comblement des vallées sylviennes (scissures latérales) et de la scissure interhémisphérique</span></li>\n        <li>Comblement des <span><span class=\"nc-purple_bg\">sillons corticaux</span></span> (<span>effacement du dessin normal des circonvolutions</span>)</li>\n        <li>Aspect en <span>« moulage » du polygone de Willis</span> si saignement massif</li>\n        <li>Complications associées à rechercher : <span><span class=\"nc-orange_bg\">hématome intra-parenchymateux</span></span>, <span><span class=\"nc-orange_bg\">hémorragie intra-ventriculaire</span></span>, <span><span class=\"nc-red_bg\">hydrocéphalie aiguë</span></span></li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/341/tdm-hsa-hip-associe.png\" alt=\"TDM cérébrale non injectée : hémorragie sous-arachnoïdienne compliquée d&#x27;un hématome intra-parenchymateux\">\n        <figcaption>HSA compliquée d'un <span>hématome intra-parenchymateux</span> — l'hyperdensité sous-arachnoïdienne s'associe à une <span>collection hyperdense intra-cérébrale</span> (hémorragie cérébro-méningée).</figcaption>\n      </figure>\n      <div class=\"callout\"><p>La visibilité du <span class=\"nc-red nc-bold\">sang</span> décroît avec le temps : une imagerie tardive normale ne suffit pas à exclure une HSA. Compléter selon la présentation et le protocole spécialisé.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li></ul><p></p></details>","frequence":1},{"id":"341-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration complémentaire à visée étiologique","contenu":"<div class=\"notion-course\"><p>Dès que l'HSA est confirmée, une <strong>exploration étiologique</strong> est lancée pour identifier l'anévrisme et orienter la prise en charge.</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Modalités et indications</th></tr></thead>\n        <tbody>\n          <tr><td>1ʳᵉ intention</td><td><strong>Examen :</strong> <span>angioTDM cérébrale</span> avec reconstruction 3D, non invasive<br><strong>Délai :</strong> immédiatement après le <span>TDM</span> non injecté ayant montré l'HSA<br><strong>Apport :</strong> reconstruction 3D du <span>polygone de Willis</span> → visualise l'anévrisme (<span>image d'addition</span>), précise sa morphologie et ses rapports → oriente la PEC</td></tr>\n          <tr><td>Alternative</td><td><strong>Examen :</strong> <span>ARM</span> (<span>angio-IRM</span>)<br><strong>Limite :</strong> résolution anatomique inférieure à celle de l'<span>angioTDM</span></td></tr>\n          <tr><td>2ⁿᵈᵉ intention</td><td>Artériographie cérébrale si angio-TDM non concluante ou pour préciser/traiter une lésion. Répétition éventuelle selon distribution du sang, qualité du bilan initial et avis neuroradiologique ; pas de calendrier universel.</td></tr>\n          <tr><td>Autres (cas par cas)</td><td><strong>Selon le contexte :</strong> <span>hémocultures</span> si suspicion d'<span>anévrisme mycotique</span> (complication d'<span>endocardite infectieuse</span>) ; <span>échographie rénale</span> (<span>polykystose</span>) ; <span>biopsie de peau</span> (affections du collagène)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout\"><p>Une HSA périmésencéphalique typique peut avoir un bilan et un suivi différents ; son caractère non anévrismal doit être établi par l’équipe spécialisée.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li></ul><p></p></details>","frequence":1},{"id":"341-9","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’urgence d’une hémorragie méningée","contenu":"<div class=\"notion-course\"><div class=\"callout callout-danger\">\n        <strong><span>Urgence</span> vitale absolue.</strong> <span>Mortalité</span> globale <span>40-50 %</span>, dont <span>10-20 %</span> de <span class=\"nc-red_bg\">décès</span> <span>avant l'arrivée à l'hôpital</span>. Toute suspicion d'HSA impose un <span>transfert urgent et médicalisé</span> vers un centre disposant d'une unité de <span>neurochirurgie</span>, de <span>neuroradiologie interventionnelle</span> et de <span>neuroréanimation</span>.\n      </div>\n      <p>L'<span>urgence</span> se décline sur <strong>trois plans</strong> :</p>\n      <table>\n        <thead><tr><th>Plan</th><th>Action immédiate</th></tr></thead>\n        <tbody>\n          <tr><td>Diagnostique</td><td><span>TDM cérébral sans injection</span> en 1ʳᵉ intention, sans délai</td></tr>\n          <tr><td>Étiologique</td><td><span>angioTDM</span> immédiat dès l'HSA confirmée</td></tr>\n          <tr><td>Thérapeutique</td><td>Exclusion de l’anévrisme rompu le plus tôt possible ; les recommandations AHA/ASA 2023 privilégient un traitement dans les 24 h. Ne pas attendre 48 h par principe.</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li><li><a href=\"https://professional.heart.org/en/science-news/2023-guideline-for-the-management-of-patients-with-aneurysmal-subarachnoid-hemorrhage/top-things-to-know\" target=\"_blank\" rel=\"noopener noreferrer\">AHA/ASA · HSA anévrismale, recommandations 2023</a></li></ul><p></p></details>","frequence":0},{"id":"341-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement symptomatique initial","contenu":"<div class=\"notion-course\"><h4>Traitement et transfert spécialisé en parallèle</h4><ul><li>ABCDE, surveillance neurologique et cardiorespiratoire, antalgie/antiémétique adaptés, protection des voies aériennes si nécessaire. Informer rapidement neurochirurgie, neuroradiologie interventionnelle et neuroréanimation.</li><li>Éviter hypoxie, hypotension et variations tensionnelles importantes. Contrôle tensionnel selon protocole spécialisé avant sécurisation de l’anévrisme ; maintenir l’euvolémie.</li><li>Anticoagulant : arrêt et réversion urgente adaptée à la molécule. La gestion des antiagrégants est individualisée ; il n’existe pas d’antagonisation automatique équivalente pour tous les médicaments.</li><li><span class=\"nc-pink_bg\">Nimodipine</span> précoce, préférentiellement par voie entérale, pour réduire l’ischémie retardée et améliorer le devenir ; schéma habituel sur <span class=\"nc-pink nc-bold\">21 jours</span>, surveillance de la pression artérielle. La voie IV n’est pas une alternative indifférente.</li><li>Traiter une crise ; prophylaxie antiépileptique non systématique, discussion pour situations à haut risque. Prévention veineuse mécanique puis pharmacologique selon sécurisation et risque hémorragique.</li><li>Hydrocéphalie symptomatique : drainage urgent selon équipe. Prévention de l’ulcère de stress selon facteurs de risque, pas systématique pour toute HSA.</li></ul><p>Surveillance répétée de conscience, pupilles, déficit, natrémie et complications cardiorespiratoires. Le <span class=\"nc-blue_bg\">Doppler transcrânien</span> aide au suivi mais ne suffit pas à diagnostiquer toute ischémie retardée. La durée des soins intensifs dépend de la gravité et du risque.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li><li><a href=\"https://professional.heart.org/en/science-news/2023-guideline-for-the-management-of-patients-with-aneurysmal-subarachnoid-hemorrhage/top-things-to-know\" target=\"_blank\" rel=\"noopener noreferrer\">AHA/ASA · HSA anévrismale, recommandations 2023</a></li></ul><p></p></details>","frequence":0},{"id":"341-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement étiologique","contenu":"<div class=\"notion-course\"><p>Exclure l’anévrisme rompu dès que possible, de préférence dans les 24 h selon AHA/ASA 2023. Le choix entre coiling et clippage associe équipe endovasculaire et neurochirurgicale selon anatomie, état clinique et lésions associées.</p>\n      <table>\n        <thead><tr><th>Technique</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Endovasculaire — embolisation (1ʳᵉ intention)</td><td><strong>Principe :</strong> montée d'un <span>microcathéter</span> par voie artérielle jusque dans le sac, dépôt in situ de <span><span class=\"nc-pink nc-bold\">coils</span> en <span class=\"nc-pink nc-bold\">spires métalliques</span></span>, sous <span>anesthésie générale</span><br><strong>Avantage :</strong> <span>morbidité moindre</span> ; préférée si les 2 techniques sont possibles à risque et probabilité d'occlusion équivalents</td></tr>\n          <tr><td>Chirurgical — clippage</td><td><strong>Principe :</strong> <span><span class=\"nc-pink nc-bold\">craniotomie</span></span>, <span>dissection</span> sous microscope opératoire, pose d'un <span><span class=\"nc-pink nc-bold\">clip en titane</span></span> sur le collet de l'anévrisme<br><strong>Avantage :</strong> permet d'associer d'autres gestes — évacuation d'un <span><span class=\"nc-orange_bg\">hématome intra-parenchymateux</span></span> par effet de <span>masse</span>, <span>dérivation ventriculaire</span> si hydrocéphalie, <span>craniectomie décompressive</span> si <span>HTIC</span> pure</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout\"><p>Les deux techniques sont possibles ; leur indication dépend du cas. Ne pas cocher automatiquement les deux dans toute question thérapeutique.</p></div>\n      <p><strong>Cas particuliers</strong> :</p>\n      <ul>\n        <li><span>HSA péri-mésencéphalique idiopathique</span> : pas de traitement étiologique spécifique, <span>surveillance</span>, <span><span class=\"nc-green nc-bold\">bon pronostic</span></span></li>\n        <li><span>Anévrisme mycotique</span> : <span>antibiothérapie</span> de l'endocardite infectieuse + discussion de l'exclusion</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li><li><a href=\"https://professional.heart.org/en/science-news/2023-guideline-for-the-management-of-patients-with-aneurysmal-subarachnoid-hemorrhage/top-things-to-know\" target=\"_blank\" rel=\"noopener noreferrer\">AHA/ASA · HSA anévrismale, recommandations 2023</a></li></ul><p></p></details>","frequence":0},{"id":"341-12","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications évolutives d’une hémorragie méningée","contenu":"<div class=\"notion-course\"><h4>Complications : surveiller et réévaluer toute aggravation</h4><table><thead><tr><th>Complication</th><th>Repères et conduite</th></tr></thead><tbody><tr><td>Resaignement</td><td>Risque maximal très précocement ; sécurisation rapide de l’anévrisme, contrôle urgent devant aggravation.</td></tr><tr><td><span class=\"nc-red_bg\">Hydrocéphalie aiguë</span> / HTIC</td><td>Baisse de vigilance, vomissements, anomalies pupillaires ; imagerie et discussion de drainage urgent avec l’équipe. Ne pas imposer un ordre universel entre drainage et traitement anévrismal.</td></tr><tr><td><span class=\"nc-red_bg\">Ischémie cérébrale retardée</span></td><td>Souvent entre J4 et J14 ; déficit nouveau ou baisse de vigilance. Rechercher aussi resaignement, hydrocéphalie, crise et cause générale. Doppler, imagerie vasculaire/perfusion et autres examens selon suspicion.</td></tr><tr><td><span class=\"nc-brown_bg\">Vasospasme</span></td><td>Rétrécissement artériel radiologique, pouvant contribuer à l’ischémie retardée mais non synonyme de celle-ci. Prévention par <span class=\"nc-pink_bg\">nimodipine</span> et maintien de l’euvolémie ; traitement spécialisé si complication.</td></tr><tr><td>Troubles hydroélectrolytiques</td><td><span class=\"nc-red_bg\">Hyponatrémie</span> : distinguer mécanisme et volémie ; éviter la restriction hydrique réflexe susceptible d’aggraver la perfusion cérébrale.</td></tr><tr><td>Complications générales</td><td>Troubles du <span class=\"nc-orange_bg\">rythme</span>, dysfonction myocardique, œdème pulmonaire, fièvre, infections, complications thromboemboliques ou des soins.</td></tr><tr><td>Crises</td><td>Traiter les crises ; EEG si conscience anormale inexpliquée ou suspicion d’<span class=\"nc-brown_bg\">état de mal</span> non convulsif.</td></tr><tr><td>À distance</td><td>Hydrocéphalie chronique (marche, cognition, sphincters), <span class=\"nc-orange_bg\">épilepsie</span>, troubles cognitifs/comportementaux, fatigue et retentissement socioprofessionnel ; rééducation et suivi adaptés.</td></tr></tbody></table><p>Les délais sont des repères de surveillance, pas des exclusions diagnostiques. La durée des soins intensifs est adaptée à la gravité et aux complications.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hémorragie méningée non traumatique (341)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Hémorragie méningée</a></li><li><a href=\"https://professional.heart.org/en/science-news/2023-guideline-for-the-management-of-patients-with-aneurysmal-subarachnoid-hemorrhage/top-things-to-know\" target=\"_blank\" rel=\"noopener noreferrer\">AHA/ASA · HSA anévrismale, recommandations 2023</a></li></ul><p></p></details>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/cerebral-vasospasm-following-subarachnoid-haemorrhage","label":"Radiopaedia : Cerebral vasospasm following subarachnoid haemorrhage"}]}],"astuces":[{"type":"piege","titre":"Scanner négatif","contenu":"<div class=\"notion-course\"><p>Délai et qualité comptent ; poursuivre si suspicion persistante.</p></div>"},{"type":"piege","titre":"Resaignement","contenu":"<div class=\"notion-course\"><p>Sécuriser l’anévrisme au plus tôt.</p></div>"},{"type":"piege","titre":"Aggravation","contenu":"<div class=\"notion-course\"><p>Ne pas attribuer automatiquement tout déficit retardé au <span class=\"nc-brown_bg\">vasospasme</span>.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Céphalée brutale : urgence, TDM sans injection.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>HSA confirmée : exploration vasculaire ; bilan négatif discordant : investigations spécialisées.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Stabiliser et transférer en centre spécialisé.</li><li>Sécuriser la cause, prévenir et dépister les complications.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique","label":"CEN · Hémorragie méningée ↗"},{"href":"https://www.nice.org.uk/guidance/ng228/chapter/Recommendations","label":"NICE NG228 · Diagnostic et prise en charge de l’HSA ↗"},{"href":"https://professional.heart.org/en/science-news/2023-guideline-for-the-management-of-patients-with-aneurysmal-subarachnoid-hemorrhage/top-things-to-know","label":"AHA/ASA · HSA anévrismale, recommandations 2023 ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Céphalée brutale ou signe neurologique inquiétant ?","detail":"<ul><li>Évaluer ABC, conscience, pupilles et déficit ; avis urgent.</li></ul>","branches":[{"label":"Suspicion d’HSA","to":"tdm"}]},{"id":"tdm","kind":"decision","label":"TDM sans injection en urgence","detail":"<ul><li>Rechercher sang, hématome, hydrocéphalie et effet de masse.</li></ul>","branches":[{"label":"HSA visible","to":"vasculaire"},{"label":"TDM négative / douteuse","to":"contexte"}]},{"id":"contexte","kind":"decision","label":"La suspicion reste-t-elle significative ?","detail":"<ul><li>Revoir délai, qualité de l’examen et tableau clinique avec le spécialiste.</li></ul>","branches":[{"label":"Oui / doute persistant","to":"pl"},{"label":"Cause alternative suffisamment établie","to":"autre"}]},{"id":"pl","kind":"decision","label":"PL indiquée et sûre ?","detail":"<ul><li>Délai adapté pour bilirubine ; vérifier risque d’engagement et hémostase.</li></ul>","branches":[{"label":"Oui","to":"lcs"},{"label":"Non / impossible","to":"completer"}]},{"id":"lcs","kind":"decision","label":"Interpréter le LCS avec la clinique","detail":"<ul><li>Hématies, bilirubine/xanthochromie et conditions du prélèvement.</li></ul>","branches":[{"label":"HSA retenue","to":"vasculaire"},{"label":"Négatif concordant","to":"autre"},{"label":"Équivoque / discordant","to":"completer"}]},{"id":"completer","kind":"uncertain","label":"Investigations spécialisées et surveillance","detail":"<ul><li>IRM et/ou exploration vasculaire selon la question ; ne pas annoncer HSA exclue.</li></ul>","branches":[]},{"id":"vasculaire","kind":"urgent","label":"Explorer la cause et sécuriser","detail":"<ul><li>Angio-TDM, artériographie si indiquée ; équipe neurovasculaire/neurochirurgicale.</li></ul>","branches":[]},{"id":"autre","kind":"finish","label":"Prendre en charge la cause et donner les consignes","detail":"<ul><li>Une céphalée en coup de tonnerre peut avoir d’autres causes graves.</li></ul>","branches":[]}]},"cards":[{"i":"18218d1998ca","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quelles sont les préventions médicamenteuses et physiques à initier dès la prise en charge d'une hémorragie méningée non traumatique (HMNT) ?","a":"<div class=\"notion-course\"><p><span class=\"nc-pink_bg\">Nimodipine</span> précoce préférentiellement entérale, habituellement <span class=\"nc-pink nc-bold\">21 jours</span> sous surveillance ; prévention veineuse adaptée après sécurisation. Pas de prévention systématique de l’ulcère de stress sans facteur de risque.</p></div>"},{"i":"2268009c0c32","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Comment doit être gérée l'hémodynamique, la ventilation et l'hémostase en phase initiale d'une hémorragie méningée non traumatique (HMNT) ?","a":"<div class=\"notion-course\"><p>ABCDE, euvolémie, éviter hypoxie/hypotension ; protection des voies aériennes si nécessaire. Réversion urgente d’un anticoagulant selon molécule ; gestion individualisée des antiagrégants, sans antagonisation universelle.</p></div>"},{"i":"a35f5a4f7a2b","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quels sont les traitements symptomatiques spécifiques à administrer en urgence lors d'une hémorragie méningée non traumatique (HMNT) ?","a":"<div class=\"notion-course\"><p>Antalgie/antiémétique adaptés, contrôle tensionnel surveillé selon protocole, traitement des crises. Pas de prophylaxie antiépileptique systématique ; discuter les terrains à haut risque.</p></div>"},{"i":"b129b9c4a6ce","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quelle surveillance est impérative et quels signes faut-il rechercher en continu lors du traitement initial d'une hémorragie méningée non traumatique (HMNT) ?","a":"<div class=\"notion-course\"><p>Surveillance neurologique et cardiorespiratoire répétée, natrémie et volémie ; rechercher resaignement, hydrocéphalie et ischémie retardée. <span class=\"nc-blue_bg\">Doppler transcrânien</span> utile mais non suffisant ; durée selon gravité.</p></div>"},{"i":"d402ead6a4b6","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quelle est l'attitude initiale et les premières mesures de conditionnement à adopter pour la prise en charge d'une hémorragie méningée non traumatique (HMNT) en urgence ?","a":"<div class=\"notion-course\"><p>Stabilisation, surveillance, antalgie et avis/transfert spécialisé sans délai. Pas de prise orale non sécurisée ; la voie entérale est <span class=\"nc-green_bg\">discutée</span> avec l’équipe. Une HTIC seule n’est pas une contre-indication générale à toute sonde gastrique.</p></div>"},{"i":"11655d6a282d","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Quelle exploration complémentaire doit être réalisée immédiatement après la confirmation d'une hémorragie méningée, et dans quel but ?","a":"<div class=\"notion-course\"><p>Dès l'hémorragie méningée confirmée (par TDM ou PL positive), une <strong>angio-TDM cérébrale immédiate</strong> doit être réalisée. Son but est l'<strong>exploration étiologique</strong> pour identifier la source du saignement (par exemple, un anévrisme).</p></div>"},{"i":"6b2d772bcd6c","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Dans quel contexte l'IRM cérébrale peut-elle être utilisée dans l'exploration d'une hémorragie méningée non traumatique ?","a":"<div class=\"notion-course\"><p>IRM dans certaines situations de bilan négatif, tardif ou de PL impossible, sur décision spécialisée. Ne pas annoncer une sensibilité universelle de 100 %.</p></div>"},{"i":"8ac9b78ee830","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Quelle est la première étape de la stratégie diagnostique devant une céphalée brutale inhabituelle faisant suspecter une hémorragie méningée non traumatique ?","a":"<div class=\"notion-course\"><p>La première étape est de réaliser une <strong>TDM cérébrale sans injection en urgence</strong>.</p></div>"},{"i":"91ccf3116a07","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Dans quel cas doit-on envisager une ponction lombaire (PL) pour le diagnostic d'hémorragie méningée, et à quel délai optimal par rapport au début des céphalées ?","a":"<div class=\"notion-course\"><p>Après TDM négative si la suspicion persiste et selon protocole ; vérifier sécurité. Pour la recherche de <span class=\"nc-pink nc-bold\">bilirubine</span>/xanthochromie, au moins 12 h après le début selon NICE, sans retarder l’imagerie initiale.</p></div>"},{"i":"d45c7b1ecabf","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Quelles sont les contre-indications à la réalisation d'une ponction lombaire face à une suspicion d'hémorragie méningée ?","a":"<div class=\"notion-course\"><p>Menace d’engagement, effet de masse/hydrocéphalie obstructive, troubles de l’hémostase ou anticoagulation selon délai et molécule, instabilité : réévaluer la sécurité. Une TDM normale ne suffit pas à autoriser toute PL.</p></div>"},{"i":"0d87dee40efd","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quels sont les signes à rechercher au scanner cérébral sans injection qui peuvent orienter vers l'étiologie d'une hémorragie méningée ?","a":"<div class=\"notion-course\"><ul><li>Des <strong><span class=\"nc-blue_bg\">calcifications de la paroi anévrismale</span></strong> (plus rare) peuvent évoquer un anévrisme.</li><li>Une <strong><span class=\"nc-red nc-bold\">HSA corticale</span></strong> doit faire suspecter une étiologie non anévrismale, comme une <strong>angiopathie amyloïde</strong>, une <strong>malformation artérioveineuse</strong> (<span class=\"nc-red nc-bold\">MAV</span>) ou une <strong>thrombose veineuse cérébrale</strong>.</li></ul></div>"},{"i":"153f6b7f444c","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quelles sont les complications d'une hémorragie méningée à rechercher systématiquement dès le scanner cérébral initial ?","a":"<div class=\"notion-course\"><ul><li>L'<strong><span class=\"nc-red_bg\">hématome intraparenchymateux</span> associé</strong>.</li><li>L'<strong><span class=\"nc-red_bg\">hémorragie intraventriculaire</span></strong>.</li><li>L'<strong><span class=\"nc-red_bg\">hydrocéphalie aiguë</span></strong>, révélée par une dilatation ventriculaire.</li></ul></div>"},{"i":"237205f252b2","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quelles sont les localisations typiques de l'hyperdensité au scanner cérébral sans injection en cas d'hémorragie méningée ?","a":"<div class=\"notion-course\"><ul><li>Les <strong><span class=\"nc-purple_bg\">citernes de la base</span></strong></li><li>La <strong>vallée sylvienne</strong> (scissure latérale)</li><li>La <strong>scissure interhémisphérique</strong> (longitudinale)</li><li>Les <strong><span class=\"nc-purple_bg\">sillons corticaux</span></strong></li></ul></div>"},{"i":"4342eb573a29","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quelle est la sensibilité du scanner cérébral sans injection pour le diagnostic d'hémorragie méningée à J1 et son évolution dans le temps ?","a":"<div class=\"notion-course\"><p>Sensibilité maximale précocement, dépendante du délai, du volume de <span class=\"nc-red nc-bold\">sang</span> et de la qualité de l’examen/lecture ; elle diminue avec le temps.</p></div>"},{"i":"64fe988e81a2","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Une TDM cérébrale normale peut-elle éliminer formellement une hémorragie méningée ?","a":"<div class=\"notion-course\"><p>Pas en toutes circonstances. Tenir compte du délai et de la qualité ; si suspicion persistante, bilan complémentaire spécialisé, souvent PL si indiquée et sûre.</p></div>"},{"i":"6c28496ef423","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quel est le signe direct d'une hémorragie méningée au scanner cérébral sans injection ?","a":"<div class=\"notion-course\"><p>Le signe direct est une <strong><span class=\"nc-yellow_bg\">hyperdensité</span> <span class=\"nc-yellow_bg\">spontanée des espaces sous-arachnoïdiens</span></strong>.</p></div>"},{"i":"2c0e59d10f8e","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Dans quel contexte clinique réalise-t-on une ponction lombaire pour le diagnostic d'hémorragie méningée non traumatique ?","a":"<div class=\"notion-course\"><p>Une ponction lombaire est réalisée pour le diagnostic d'hémorragie méningée non traumatique lorsque la <strong>TDM est normale mais la suspicion clinique d'hémorragie méningée non traumatique persiste</strong>. Elle n'est <strong><span class=\"nc-red nc-bold\">jamais réalisée d'emblée</span></strong>.</p></div>"},{"i":"3c9a83b7dc86","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Qu'est-ce que la xanthochromie du liquide céphalo-rachidien et quelle est sa signification en cas de suspicion d'hémorragie méningée ?","a":"<div class=\"notion-course\"><p>Pigments du sang dans le surnageant ; la <span class=\"nc-pink nc-bold\">bilirubine</span> recherchée selon méthode validée soutient un saignement antérieur. Interpréter délai et prélèvement ; ne pas affirmer une sensibilité de 100 %.</p></div>"},{"i":"70a3da20205a","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Quels sont les critères permettant de distinguer à l'examen macroscopique une hémorragie méningée des suites d'une hémorragie sous-arachnoïdienne (HSA) d'une ponction lombaire traumatique ?","a":"<div class=\"notion-course\"><p>L’éclaircissement entre tubes et la coagulabilité ne permettent pas seuls d’exclure l’HSA. Confronter hématies, <span class=\"nc-pink nc-bold\">bilirubine</span>/xanthochromie, délai et clinique.</p></div>"},{"i":"a8a56af73778","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Jusqu'à quand la ponction lombaire reste-t-elle un examen fiable pour exclure une hémorragie sous-arachnoïdienne (HSA) ?","a":"<div class=\"notion-course\"><p>Le rendement dépend du délai, de la technique et du contexte. Il diminue au-delà d’environ deux semaines ; un résultat normal tardif ne suffit pas à exclure une HSA.</p></div>"},{"i":"de7633a30dca","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Quelles sont les caractéristiques cytologiques et biochimiques du liquide céphalo-rachidien en cas d'hémorragie sous-arachnoïdienne (HSA) ?","a":"<div class=\"notion-course\"><ul><li><strong>Cytologie</strong> : Présence de <strong>globules rouges abondants</strong> avec un rapport GR/GB &gt; 10³. On peut retrouver secondairement une leucocytose lymphocytaire et des <span class=\"nc-blue_bg\">sidérophages</span>.</li><li><strong>Biochimie</strong> : La <strong>glycorachie est normale</strong> et on observe une <strong>hyperprotéinorachie</strong>.</li></ul></div>"},{"i":"6668fa7f7f0c","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quel est le signe pivot du diagnostic de l'hémorragie méningée non traumatique à la TDM spontanée ?","a":"<div class=\"notion-course\"><p>Le signe pivot est l'<strong><span class=\"nc-yellow_bg\">hyperdensité</span> <span class=\"nc-yellow_bg\">spontanée des espaces sous-arachnoïdiens</span></strong>.</p></div>"},{"i":"7988aec87203","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quels sont les différentes localisations de l'hyperdensité spontanée à rechercher à la TDM en cas d'hémorragie sous-arachnoïdienne ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-yellow_bg\">Hyperdensité</span> spontanée des <span class=\"nc-purple_bg\">citernes de la base</span></strong> (interpédonculaire, pré-pontique, ambiantes).</li><li>Comblement des <strong>vallées sylviennes</strong> et de la <strong>scissure interhémisphérique</strong>.</li><li>Comblement des <strong><span class=\"nc-purple_bg\">sillons corticaux</span></strong> avec effacement du dessin normal des circonvolutions.</li><li>Aspect en « <strong>moulage</strong> » du polygone de Willis en cas de saignement massif.</li></ul></div>"},{"i":"adc59613bbab","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quel est le piège classique lié au délai de réalisation de la TDM dans le diagnostic d'hémorragie méningée non traumatique ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-red nc-bold\">sang</span> devient moins visible avec le temps ; une TDM tardive normale exige un bilan adapté si la suspicion persiste.</p></div>"},{"i":"b923245b0c98","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quelles complications de l'hémorragie sous-arachnoïdienne peuvent être associées et visibles à la TDM ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-orange_bg\">Hématome intra-parenchymateux</span></strong> (se présentant comme une <span class=\"nc-yellow_bg\">hyperdensité</span> intra-cérébrale associée).</li><li><strong><span class=\"nc-orange_bg\">Hémorragie intra-ventriculaire</span></strong>.</li><li><strong><span class=\"nc-red_bg\">Hydrocéphalie aiguë</span></strong>.</li></ul></div>"},{"i":"068522aa1682","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Quelle est l'urgence d'une hémorragie méningée non traumatique (HSA) ?","a":"<div class=\"notion-course\"><p>L'hémorragie méningée non traumatique (HSA) est une <strong>urgence vitale absolue</strong>, avec une mortalité globale de <strong>40 à 50%</strong>, dont 10 à 20% de <span class=\"nc-red_bg\">décès</span> avant l'arrivée à l'hôpital.</p></div>"},{"i":"25fa08edd5a0","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Comment doit se décliner l'urgence diagnostique et étiologique face à une hémorragie méningée non traumatique (HSA) ?","a":"<div class=\"notion-course\"><ul><li><strong>Diagnostic immédiat</strong> par un <strong>scanner cérébral sans injection</strong> en première intention et sans délai.</li><li><strong>Étiologique immédiat</strong> (dès l'HSA confirmée) par une <strong>angioTDM</strong>.</li></ul></div>"},{"i":"2c3203b5575c","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Quel est l'objectif thérapeutique urgent en cas d'hémorragie méningée non traumatique (HSA) et pourquoi ?","a":"<div class=\"notion-course\"><p>Sécuriser l’anévrisme rompu au plus tôt, de préférence dans les 24 h selon AHA/ASA 2023, pour réduire le resaignement précoce. Ne pas attendre 48 h par principe.</p></div>"},{"i":"56bcde11be54","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Quelle est la conduite à tenir immédiate en cas de suspicion d'hémorragie méningée non traumatique (HSA) ?","a":"<div class=\"notion-course\"><p>Toute suspicion d'HSA impose un <strong>transfert urgent et médicalisé</strong> vers un centre disposant :</p><ul><li>D'une unité de neurochirurgie</li><li>De neuroradiologie interventionnelle</li><li>De neuroréanimation</li></ul></div>"},{"i":"13023446bfc1","n":341,"o":"341-1","u":"Définition","t":"Connaître la définition de l’hémorragie méningée dite sous-arachnoïdienne, spontanée et traumatique","q":"Comment définir une HSA ?","a":"<div class=\"notion-course\"><ul><li>Présence de sang dans les espaces sous-arachnoïdiens ; distinguer contexte spontané et traumatique.</li></ul></div>"},{"i":"f0f098be8dab","n":341,"o":"341-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragies méningées et les facteurs favorisants","q":"Une petite taille exclut-elle une rupture anévrismale ?","a":"<div class=\"notion-course\"><ul><li>Non ; le risque dépend aussi de la localisation, de la forme, de la croissance et du terrain.</li></ul></div>"},{"i":"22c21cb06b51","n":341,"o":"341-3","u":"Diagnostic positif","t":"Connaître les présentations cliniques et le diagnostic d’hémorragie méningée","q":"Qu’appelle-t-on céphalée en coup de tonnerre ?","a":"<div class=\"notion-course\"><ul><li>Céphalée atteignant son maximum en moins d’une minute, nécessitant une recherche urgente de cause secondaire.</li></ul></div>"},{"i":"72b38a0cde44","n":341,"o":"341-8","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration complémentaire à visée étiologique","q":"Quand discuter une artériographie après angio-TDM ?","a":"<div class=\"notion-course\"><ul><li>Si bilan non concluant malgré suspicion ou pour préciser/traiter la lésion, selon neuroradiologie.</li></ul></div>"},{"i":"630d5a75b68f","n":341,"o":"341-11","u":"Prise en charge","t":"Connaître les principes du traitement étiologique","q":"Comment choisir coiling ou clippage ?","a":"<div class=\"notion-course\"><ul><li>Décision multidisciplinaire selon anatomie, état clinique, hématome et possibilités techniques.</li></ul></div>"},{"i":"94299fae671d","n":341,"o":"341-12","u":"Suivi et/ou pronostic","t":"Connaître les complications évolutives d’une hémorragie méningée","q":"Toute aggravation retardée est-elle un vasospasme ?","a":"<div class=\"notion-course\"><ul><li>Non : rechercher aussi resaignement, hydrocéphalie, crise, infection ou désordre métabolique.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181e6b627fd9636ab8164?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."}};
